import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2017-pm2-facts.json';
const plain=(blocks:readonly{type:string;text?:string}[])=>blocks.map(b=>{assert(b.type==='paragraph'&&typeof b.text==='string');return b.text!}).join('\n');
export function assertLegacy2017Pm2(body:GeneratedBody,variant:number){const f=facts.scenarios[variant];assert(f);assert.equal(body.prompt.length,47);assert.equal(body.choices.length,24);assert.deepEqual(body.answerParts?.map(p=>p.id),['part-a','part-b','part-c','part-d','part-e']);assert.deepEqual(body.answerParts?.map(p=>p.choiceIds.length),[5,5,5,4,5]);const cols=body.choices.map(b=>plain(b)),ordered=['a','b','c','d','e']as const;assert.deepEqual(cols,ordered.flatMap(p=>f.choices[p]));const digits=[6,4,3],d=digits[variant],code=d-1,T=10*code,lit=([variant===0?[7,5,4,3,2,1]:variant===1?[6,5,2,1]:[7,6,5,4,1]])[0],word=lit.reduce((sum,bit)=>sum+2**bit,0);const answers=[word.toString(16).toUpperCase(),code.toString(2).padStart(3,'0'),`${T-5}℃以上${T+5}℃未満`,'GR＝0','OUTPUT 1'];let offset=0;ordered.forEach((p,i)=>{const opts=f.choices[p],actual=body.partAnswers?.[i];assert(actual?.kind==='choice');const truth=opts.map(t=>t===answers[i]);assert.equal(truth.filter(Boolean).length,1);assert.deepEqual(f.truths.filter(t=>t.part===p).map(t=>t.truth),truth);assert.equal(actual.choiceId,'choice-value-'+(offset+truth.indexOf(true)+1));assert.deepEqual(body.answerParts![i].choiceIds,opts.map((_,j)=>'choice-value-'+(offset+j+1)));offset+=opts.length;});
 const expected:unknown[]=[{type:'diagram',part:0,caption:'問2～問7の選択について'}];for(const page of facts.source.pages)for(const block of page.blocks){if('text'in block)expected.push({type:'paragraph',text:block.text});else if('choices'in block){const name=block.id as 'a'|'b'|'c'|'d'|'e';expected.push({type:'paragraph',text:block.label});for(const[i,t]of f.choices[name].entries())expected.push({type:'paragraph',text:'アイウエオ'[i]+'　'+t});}else if('rows'in block){if(block.id==='table2')expected.push({type:'diagram',part:3,caption:block.caption});else expected.push({type:'table',caption:block.caption,columns:block.columns,rows:block.rows});}else if('caption'in block)expected.push({type:'diagram',part:({'figure1':1,'figure2':2,'figure3':4}as Record<string,number>)[block.id],caption:block.caption});}assert.deepEqual(body.prompt.map(b=>b.type==='diagram'?(assert(b.scene.kind==='source_figure'),{type:b.type,part:b.scene.values[1],caption:b.caption}):b.type==='table'?{type:b.type,caption:b.caption,columns:b.columns,rows:b.rows}:b.type==='paragraph'?{type:b.type,text:b.text}:{type:b.type}),expected,'complete source sequence including all printed choice groups');
 const paragraphs=body.prompt.flatMap(b=>b.type==='paragraph'?[b.text]:[]).join('\n');const originalTexts=facts.source.pages.flatMap(p=>p.blocks.flatMap(b=>'text'in b&&typeof b.text==='string'?[b.text]:[]));let at=-1;for(const t of originalTexts){const next=paragraphs.indexOf(t);assert(next>at,t);at=next;}
 const sourceBlocks: {id:string;text?:string;caption?:string;columns?:string[];rows?:string[][]}[]=facts.source.pages.reduce<{id:string;text?:string;caption?:string;columns?:string[];rows?:string[][]}[]>((a,p)=>[...a,...p.blocks],[]);const tables=body.prompt.filter(b=>b.type==='table');assert.equal(tables.length,2);for(const[index,id]of[[0,'table1'],[1,'table3']]as const){const source=sourceBlocks.find(b=>b.id===id)!;assert(source.rows&&source.columns&&source.caption);assert.equal(tables[index].caption,source.caption);assert.deepEqual(tables[index].columns,source.columns);assert.deepEqual(tables[index].rows,source.rows);}
 const indices=[0,5,11,32,35];assert.deepEqual(body.prompt.flatMap((b,i)=>b.type==='diagram'?[i]:[]),indices);indices.forEach((j,part)=>{const b=body.prompt[j];assert(b.type==='diagram'&&b.scene.kind==='source_figure');assert.equal(b.scene.profile,'legacy-2017-pm2-temperature-monitor');assert.deepEqual(b.scene.values,[variant,part]);assert(b.alt.length>30);});
 const ex=body.explanation;for(const t of[answers[0],answers[1],`${T}℃`,`${T-5}℃以上${T+5}℃未満`,'中点は高い側','下端を含み','上端は次のレベル','GR＝0','INPUT 2','非0','INPUT 3','OUTPUT 1','INPUT 1/2/3','OUTPUT 2','規定されておらず','符号解釈','小数点のビット0'])assert(ex.includes(t),t);for(const t of['GRは常に非負','完了値は1だけ','OUTPUT 2で必ず再変換'])assert(!ex.includes(t));assert(ex.includes('66は数字4、BEは6、DAは2、F2は3、FEは8'));return{truths:24,correct:answers};
}
